// Flue (Cloudflare target) + the Cloudflare Vite plugin. flue() must come first: it generates the Worker entry and
// one Durable Object class per agent; flueWorkerConfig() hands those to the Cloudflare plugin.
// WRANGLER_CONFIG picks the config: wrangler.jsonc (template, for checks), wrangler.local.jsonc (your real ids,
// git-ignored) or wrangler.ci.jsonc (generated by tools/ci_config.mjs in Workers Builds).
import { cloudflare } from "@cloudflare/vite-plugin";
import { flue, flueWorkerConfig } from "@flue/vite";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [
    flue({ providers: ["cloudflare"] }), // Claude is reached through the Workers AI binding → AI Gateway; nothing else ships
    cloudflare({ configPath: process.env.WRANGLER_CONFIG || "wrangler.jsonc", config: flueWorkerConfig() }),
  ],
});
